const zakupy = ["chleb", "mleko", "chleb", "jajka", "mleko", "chleb"];
const licznik = new Map();

for (const produkt of zakupy) {
  licznik.set(produkt, (licznik.get(produkt) ?? 0) + 1);
}

console.log(licznik); // Map { "chleb" => 3, "mleko" => 2, "jajka" => 1 }

// Set zamiast Array: gdy liczy sie unikalnosc elementow i potrzebujesz
// szybkiego sprawdzania przynaleznosci przez .has().
// Map zamiast Object: gdy klucze sa dynamiczne (nieznane z gory) lub
// wymagaja typu innego niz string, a takze gdy wazna jest gwarantowana
// kolejnosc iteracji.

const dozwoloneRole = new Set(["admin", "moderator", "uzytkownik"]);

function maDostep(rola) {
  return dozwoloneRole.has(rola);
}

console.log(maDostep("admin")); // true
console.log(maDostep("gosc"));  // false

const oceny = [3, 4, 4, 5, 3, 3, 5, 2];
const licznikMap = new Map();

for (const ocena of oceny) {
  licznikMap.set(ocena, (licznikMap.get(ocena) ?? 0) + 1);
}

const wynikObj = Object.fromEntries(licznikMap);
console.log(wynikObj); // { "3": 3, "4": 2, "5": 2, "2": 1 }

const liczby = Array.from({ length: 1000 }, (_, i) => i + 1);
const zbiorLiczb = new Set(liczby);

console.log(zbiorLiczb.has(500));  // true
console.log(zbiorLiczb.has(1500)); // false
// Set.has() jest wydajniejsze niz Array.includes() dla duzych zbiorow -
// przy tysiacach elementow roznica w wydajnosci staje sie zauwazalna,
// szczegolnie gdy sprawdzenie przynaleznosci wykonywane jest wielokrotnie
// (np. w petli), dlatego Set jest naturalnym wyborem dla tego scenariusza.

const uzytkownik = { imie: "Jan", wiek: 30 };
// Reprezentowanie tych danych przez Map (np. new Map().set("imie", "Jan"))
// bylowoby niepotrzebnie zlozone, poniewaz pola "imie" i "wiek" sa ZNANE
// Z GORY i NIGDY sie nie zmieniaja - to klasyczny przypadek dla zwyklego
// obiektu literalowego, ktory jest prostszy w zapisie, latwiejszy do
// serializacji przez JSON.stringify(), i bardziej naturalny dla "rekordu"
// o stalej strukturze.

const tagi = ["react", "js", "react", "css", "js", "react"];
const licznik = new Map();

for (const tag of tagi) {
  licznik.set(tag, (licznik.get(tag) ?? 0) + 1);
}

let najczestszyTag = null;
let najwiekszaLiczba = 0;

for (const [tag, liczba] of licznik) {
  if (liczba > najwiekszaLiczba) {
    najczestszyTag = tag;
    najwiekszaLiczba = liczba;
  }
}

console.log(najczestszyTag); // "react" (3 wystapienia)

// Uzywanie Map/Set 'wszedzie na wszelki wypadek' jest bledna praktyka,
// poniewaz:
// 1. Zwykly obiekt/tablica sa CZESTO prostsze i bardziej czytelne dla
//    typowych, znanych 'z gory' struktur danych (np. rekordow z ustalonymi
//    polami).
// 2. Object/Array daje sie BEZPOSREDNIO zserializowac przez
//    JSON.stringify() - Map/Set wymagaja dodatkowej konwersji (przez
//    Object.fromEntries()/Array.from()), zanim beda mogly zostac wyslane
//    jako JSON.
// 3. Wiekszosc programistow jest BARDZIEJ oswojona ze skladnia obiektow i
//    tablic, wiec niepotrzebne uzycie Map/Set utrudnia czytanie kodu bez
//    faktycznej korzysci.
